package com.orderflow.delivery.service;
import com.orderflow.delivery.domain.*;import com.orderflow.delivery.repository.*;import com.orderflow.events.*;import io.micrometer.core.instrument.MeterRegistry;import java.time.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DeliveryWorkflowService{static final String CONSUMER="delivery-order-events-v1";private final DeliveryRepository deliveries;private final DeliveryStatusHistoryRepository history;private final DeliveryAgentRepository agents;private final ProcessedEventStore processed;private final DeliveryAssignmentService assignment;private final DeliveryEventOutbox events;private final MeterRegistry metrics;private final Clock clock;public DeliveryWorkflowService(DeliveryRepository d,DeliveryStatusHistoryRepository h,DeliveryAgentRepository a,ProcessedEventStore p,DeliveryAssignmentService s,DeliveryEventOutbox e,MeterRegistry m,Clock c){deliveries=d;history=h;agents=a;processed=p;assignment=s;events=e;metrics=m;clock=c;}
 @Transactional public void requested(DeliveryRequestedEvent event){event.metadata().require(EventType.DELIVERY_REQUESTED,1);if(processed.contains(event.metadata(),CONSUMER))return;Delivery d=deliveries.findByOrderId(event.orderId()).orElseGet(()->{Instant now=Instant.now(clock);Delivery value=Delivery.create(event.orderId(),event.customerId(),event.shippingAddress(),now);deliveries.saveAndFlush(value);history.save(new DeliveryStatusHistory(value.getId(),null,value.getStatus(),null,event.metadata().eventId(),event.metadata().correlationId(),now));metrics.counter("delivery_requests_total").increment();return value;});processed.add(event.metadata(),CONSUMER);assignment.autoAssign(d.getId(),event.metadata().correlationId(),event.metadata().eventId());}
 @Transactional public void cancel(DeliveryCancelRequestedEvent event){event.metadata().require(EventType.DELIVERY_CANCEL_REQUESTED,1);if(processed.contains(event.metadata(),CONSUMER))return;Delivery d=deliveries.findByOrderId(event.orderId()).orElse(null);if(d!=null&&d.getStatus()!=DeliveryStatus.CANCELLED){DeliveryStatus previous=d.getStatus();d.cancel(event.reasonCode(),Instant.now(clock));release(d,Instant.now(clock));history.save(new DeliveryStatusHistory(d.getId(),previous,d.getStatus(),null,event.metadata().eventId(),event.metadata().correlationId(),Instant.now(clock)));events.cancelled(d,event.reasonCode(),event.metadata().correlationId(),event.metadata().eventId(),Instant.now(clock));metrics.counter("deliveries_cancelled_total").increment();}processed.add(event.metadata(),CONSUMER);}
 private void release(Delivery d,Instant now){if(d.getDeliveryAgentId()!=null)agents.lockById(d.getDeliveryAgentId()).ifPresent(a->a.released(now));}
}
